def check_coloring(n, r_split):
    """
    Checks if a specific coloring (R = {1..r_split}, B = {r_split+1..n}) yields 2007.
    r_split is the largest element in the Red set R.
    """
    R = set(range(1, r_split + 1))
    B = set(range(r_split + 1, n + 1))

    def count_triples(S_set):
        count = 0
        for x in S_set:
            for y in S_set:
                for z in S_set:
                    if (x + y + z) % n == 0:
                        count += 1
        return count

    N_R = count_triples(R)
    N_B = count_triples(B)

    total_N = N_R + N_B
    return total_N

target_N = 2007
results = {}

for n in range(1, 16):
    found_for_n = False
    test_cases = []

    # Test simple partition: R = {1..r}, B = {r+1..n}
    # r runs from 1 to n-1 for non-empty sets
    for r in range(1, n):
        N = check_coloring(n, r)
        if N == target_N:
            found_for_n = True
            test_cases.append((n, r, N))
        else:
            test_cases.append((n, r, N))

    results[n] = test_cases

# Print structured results for easy reading/recording
print("--- Simulation Results ---")
for n, cases in results.items():
    print(f"N = {n}:")
    if not cases:
        print("  No partitions tested (n=1 or n=2).")
        continue

    found_match = False
    for n_case, r_case, N_val in cases:
        if N_val == target_N:
            print(f"  Match found for r={r_case}: Total N = {N_val}")
            found_match = True
        # Only printing the first few cases for brevity if the list is long
        if n_case == n and r_case < 3 and not found_match:
            print(f"  r={r_case}: Total N = {N_val}")
        elif n_case == n and r_case >= 3 and not found_match and len(cases) > 5:
             # Stop printing exhaustive results if many partitions exist, focusing on the pattern
             pass

    if not found_match:
         print("  No match for N=2007 found among simple partitions.")

# Check for small n manually to ensure comprehensive logging
# We are looking for the smallest n.
print("\n--- Summary Check ---")
found_smallest_n = None
for n in sorted(results.keys()):
    match_found = False
    for n_case, r_case, N_val in results[n]:
        if N_val == target_N:
            match_found = True
            break
    if match_found:
        found_smallest_n = n
        break

print(f"Smallest n found so far: {found_smallest_n}")

